#!/usr/bin/env python3
"""Payroll summary for one period, following /app/docs/payroll-rules.md."""
import csv
import gzip
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        raw = f.read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    text = raw.decode("utf-8-sig")
    return text


def lines_of(text):
    for ln in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if ln.strip() == "":
            continue
        yield ln


def read_csv_file(path):
    text = read_text(path)
    return list(csv.DictReader(io.StringIO(text)))


def from_epoch(sec):
    return int(sec)


def std_offset(zone, ref=None):
    """Standard (non-DST) UTC offset of a zone, in seconds."""
    ref = ref or datetime(2026, 1, 15, tzinfo=UTC)
    best = None
    for m in (1, 4, 7, 10):
        d = datetime(ref.year, m, 15, 12, tzinfo=UTC).astimezone(zone)
        off = d.utcoffset() - (d.dst() or timedelta(0))
        best = off if best is None else min(best, off)
    return int(best.total_seconds())


def local_to_instant(naive, zone, prefer_dst=None):
    """Naive local wall time -> UTC epoch seconds.

    prefer_dst: None/True -> first occurrence for repeated times (DST one);
    False -> second occurrence (standard time).
    """
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() == b.utcoffset():
        dt = a
    else:
        # either repeated (a has larger offset) or gap (a has smaller offset)
        if a.utcoffset() > b.utcoffset():
            dt = b if prefer_dst is False else a
        else:
            dt = a
    return int(dt.timestamp()) if False else epoch_of(dt)


def epoch_of(dt):
    return int((dt - EPOCH) // timedelta(seconds=1))


def parse_iso_offset(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        raise ValueError("no offset: " + s)
    return epoch_of(dt)


# ---------------------------------------------------------------- readers
# Each reader yields (punch_id, employee, direction('IN'/'OUT'), instant)

def read_abbr_csv(path, zone):
    text = read_text(path)
    header = None
    for row in csv.reader(io.StringIO("\n".join(lines_of(text)))):
        if not row:
            continue
        cells = [c.strip() for c in row]
        if "Badge" in cells and "Punch" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = r["Time"].strip()
        up = t.upper()
        if up.endswith("AM") or up.endswith("PM"):
            ampm = up[-2:]
            hms = up[:-2].strip().split(":")
            h, m, s = int(hms[0]), int(hms[1]), int(hms[2]) if len(hms) > 2 else 0
            h = h % 12
            if ampm == "PM":
                h += 12
        else:
            hms = t.split(":")
            h, m, s = int(hms[0]), int(hms[1]), int(hms[2]) if len(hms) > 2 else 0
        naive = d.replace(hour=h, minute=m, second=s)
        z = r.get("Zone", "").strip().upper()
        pref = None
        if z.endswith("DT"):
            pref = True
        elif z.endswith("ST"):
            pref = False
        yield (r["Record"], r["Badge"], r["Punch"].strip().upper(),
               local_to_instant(naive, zone, pref))


def read_epoch_jsonl(path, zone):
    schema = 1
    for ln in lines_of(read_text(path)):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if "schema" in o and len(o) == 1:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat") is True:
            continue
        if schema == 2:
            if "punch_id" not in o:
                continue
            ms = o["epoch_ms"]
            inst = int(Decimal(str(ms)) // 1000) if not isinstance(ms, int) else ms // 1000
            yield (str(o["punch_id"]), o["employee"], str(o["direction"]).upper(), inst)
        else:
            if "id" not in o:
                continue
            if "ts_ms" in o:
                ms = o["ts_ms"]
                inst = ms // 1000 if isinstance(ms, int) else int(Decimal(str(ms)) // 1000)
            else:
                ts = o["ts"]
                inst = ts if isinstance(ts, int) else int(Decimal(str(ts)) // 1)
            yield (str(o["id"]), o["emp"], str(o["dir"]).upper(), inst)


def read_offset_csv(path, zone):
    text = read_text(path)
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text))), delimiter=";"):
        r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
        ev = r["event"].lower()
        d = "IN" if ev.endswith("in") else "OUT"
        yield (r["punch_id"], r["employee"], d, parse_iso_offset(r["timestamp"]))


def parse_off(s):
    sign = -1 if s[0] == "-" else 1
    return sign * (int(s[1:3]) * 3600 + int(s[3:5]) * 60)


def read_legacy(path, zone):
    off = std_offset(zone)
    for ln in lines_of(read_text(path)):
        t = ln[:1]
        if t == "H":
            tail = ln[13:18].strip()
            if len(tail) == 5 and tail[0] in "+-":
                off = parse_off(tail)
            else:
                off = std_offset(zone)
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            dr = ln[15:16]
            dt = datetime.strptime(ln[16:30], "%Y%m%d%H%M%S").replace(tzinfo=UTC)
            inst = epoch_of(dt) - off
            yield (pid, "E" + badge, "IN" if dr == "I" else "OUT", inst)


def read_de_tsv(path, zone):
    header = None
    for ln in lines_of(read_text(path)):
        cells = [c.strip() for c in ln.split("\t")]
        if "Ausweis" in cells and "Buchung" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = datetime.strptime(r["Datum"], "%d.%m.%Y")
        hm = r["Uhrzeit"].split(":")
        naive = d.replace(hour=int(hm[0]), minute=int(hm[1]),
                          second=int(hm[2]) if len(hm) > 2 else 0)
        z = r.get("Zeitzone", "").upper()
        pref = None
        if z == "MESZ":
            pref = True
        elif z == "MEZ":
            pref = False
        yield (r["Nr"], r["Ausweis"], "IN" if r["Buchung"].upper() == "K" else "OUT",
               local_to_instant(naive, zone, pref))


def read_local_csv(path, zone):
    text = read_text(path)
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text)))):
        r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
        naive = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
        yield (r["punch_ref"], r["employee_id"], r["direction"].upper(),
               local_to_instant(naive, zone, True))


def read_local_jsonl(path, zone):
    for ln in lines_of(read_text(path)):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        p = o.get("punch") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        yield (str(p["id"]), p["badge"], str(p["type"]).upper(),
               local_to_instant(naive, zone, True))


READERS = {
    "abbr-csv": read_abbr_csv,
    "epoch-jsonl": read_epoch_jsonl,
    "offset-csv": read_offset_csv,
    "legacy-fixed": read_legacy,
    "de-tsv": read_de_tsv,
    "local-csv": read_local_csv,
    "local-jsonl": read_local_jsonl,
}


# ---------------------------------------------------------------- main logic
def main(indir, outfile):
    with open(os.path.join(indir, "period.json")) as f:
        period = json.load(f)
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso_offset(period["corrections_cutoff"])

    sites = {}
    for r in read_csv_file(os.path.join(indir, "sites.csv")):
        sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = {}
    for r in read_csv_file(os.path.join(indir, "employees.csv")):
        employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    for r in read_csv_file(os.path.join(indir, "rates.csv")):
        rates.setdefault(r["employee_id"].strip(), []).append(
            (date.fromisoformat(r["effective_from"].strip()), Decimal(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect punches
    punches = {}   # (site, id) -> dict(emp, dir, t)
    ever = set()
    for site in sorted(sites):
        zone, fmt = sites[site]
        base = os.path.join(indir, "exports", site)
        if not os.path.isdir(base):
            continue
        files = []
        for root, _, names in os.walk(base):
            for n in names:
                files.append(os.path.join(root, n))
        for path in sorted(files):
            for pid, emp, d, inst in READERS[fmt](path, zone):
                key = (site, pid.strip() if fmt != "legacy-fixed" else pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = {"emp": emp.strip(), "dir": d, "t": inst}

    # 2. corrections
    corr = []
    cdir = os.path.join(indir, "corrections")
    if os.path.isdir(cdir):
        for root, _, names in os.walk(cdir):
            for n in sorted(names):
                p = os.path.join(root, n)
                try:
                    rows = read_csv_file(p)
                except Exception:
                    continue
                for r in rows:
                    r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                    if not r.get("correction_id") or r.get("action", "") == "action":
                        continue
                    corr.append(r)
    keyed = []
    for r in corr:
        try:
            keyed.append((parse_iso_offset(r["issued_at"]), r["correction_id"], r))
        except Exception:
            continue
    keyed.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    voided = set()
    for issued, _, r in keyed:
        if issued > cutoff:
            continue
        act = r["action"].lower()
        key = (r["site"], r["punch_id"])
        exists = key in punches and key not in voided
        if act == "void":
            if exists:
                voided.add(key)
                del punches[key]
                applied += 1
        elif act == "set":
            if exists:
                try:
                    punches[key]["t"] = parse_iso_offset(r["time"])
                except Exception:
                    continue
                applied += 1
        elif act == "add":
            if key in ever or r["site"] not in sites:
                continue
            try:
                t = parse_iso_offset(r["time"])
            except Exception:
                continue
            ever.add(key)
            punches[key] = {"emp": r["employee"], "dir": r["type"].upper(), "t": t}
            applied += 1

    byemp = {}
    for (site, pid), p in punches.items():
        if p["emp"] not in employees:
            continue
        byemp.setdefault(p["emp"], []).append(
            {"site": site, "id": pid, "dir": p["dir"], "t": p["t"]})

    zones = {s: sites[s][0] for s in sites}

    def offset_at(zone, inst):
        return int(datetime.fromtimestamp(inst, UTC).astimezone(zone).utcoffset().total_seconds())

    def round_t(site, inst):
        off = offset_at(zones[site], inst)
        loc = inst + off
        r = loc % 360
        loc2 = loc - r + (360 if r >= 180 else 0)
        return inst + (loc2 - loc)

    def workday(emp, inst):
        hz = zones[employees[emp]] if employees[emp] in zones else UTC
        return datetime.fromtimestamp(inst, UTC).astimezone(hz).date()

    def in_period(d):
        return pstart <= d <= pend

    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0,
           "corrections_applied": applied}
    result_emps = {}
    for emp in employees:
        result_emps[emp] = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0,
                            "night_minutes": 0, "gross": "0.00"}

    for emp, plist in byemp.items():
        plist.sort(key=lambda p: (p["t"], 0 if p["dir"] == "OUT" else 1, p["site"], p["id"]))
        # 3. duplicates
        kept = []
        for p in plist:
            p["r"] = round_t(p["site"], p["t"])
            if kept and kept[-1]["dir"] == p["dir"] and p["t"] - kept[-1]["t"] <= 300:
                if in_period(workday(emp, p["r"])):
                    exc["duplicates_dropped"] += 1
                continue
            kept.append(p)
        # 5. pair
        shifts = []
        i = 0
        n = len(kept)
        pending = None  # current unmatched IN
        for p in kept:
            if p["dir"] == "IN":
                if pending is not None:
                    if in_period(workday(emp, pending["r"])):
                        exc["open_shifts"] += 1
                pending = p
            else:
                if pending is not None and p["r"] - pending["r"] <= 16 * 3600:
                    shifts.append((pending, p))
                    pending = None
                else:
                    if in_period(workday(emp, p["r"])):
                        exc["orphan_outs"] += 1
                    if pending is not None:
                        if in_period(workday(emp, pending["r"])):
                            exc["open_shifts"] += 1
                        pending = None
        if pending is not None and in_period(workday(emp, pending["r"])):
            exc["open_shifts"] += 1

        # 7. minutes
        rows = []
        for pin, pout in shifts:
            wd = workday(emp, pin["r"])
            if not in_period(wd):
                continue
            worked = max(0, (pout["r"] - pin["r"]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = night_minutes(zones[pin["site"]], pin["r"], pout["r"])
            night = min(night, paid)
            rows.append({"in": pin["r"], "wd": wd, "paid": paid, "night": night, "ot": 0})
        rows.sort(key=lambda r: r["in"])
        # 8. overtime
        daily = {}
        for r in rows:
            before = daily.get(r["wd"], 0)
            after = before + r["paid"]
            daily[r["wd"]] = after
            r["dot"] = max(0, after - max(before, 480))
        weekly = {}
        for r in rows:
            wk = r["wd"] - timedelta(days=r["wd"].weekday())
            before = weekly.get(wk, 0)
            nd = r["paid"] - r["dot"]
            after = before + nd
            weekly[wk] = after
            r["wot"] = max(0, after - max(before, 2400))
            r["ot"] = r["dot"] + r["wot"]
        # 9. pay
        total = Fraction(0)
        for r in rows:
            rate = None
            for eff, val in rates.get(emp, []):
                if eff <= r["wd"]:
                    rate = val
            if rate is None:
                continue
            rate = Fraction(rate)
            reg = r["paid"] - r["ot"]
            total += rate * (reg + Fraction(3, 2) * r["ot"]) / 60
            total += rate * Fraction(15, 100) * r["night"] / 60
        cents = total * 100
        c = int(cents + Fraction(1, 2) // 1) if False else (cents.numerator * 2 + cents.denominator) // (2 * cents.denominator)
        e = result_emps[emp]
        e["shifts"] = len(rows)
        e["paid_minutes"] = sum(r["paid"] for r in rows)
        e["overtime_minutes"] = sum(r["ot"] for r in rows)
        e["night_minutes"] = sum(r["night"] for r in rows)
        e["gross"] = "%d.%02d" % divmod(c, 100)

    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    gross_c = 0
    for e in result_emps.values():
        for k in tot:
            tot[k] += e[k]
        a, b = e["gross"].split(".")
        gross_c += int(a) * 100 + int(b)
    tot["gross"] = "%d.%02d" % divmod(gross_c, 100)

    out = {"period": {"start": period["start"], "end": period["end"]},
           "employees": result_emps, "exceptions": exc, "totals": tot}
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w") as f:
        json.dump(out, f, indent=1)


def night_minutes(zone, t0, t1):
    """Minutes of [t0, t1) between 22:00 and 06:00 local time of zone."""
    if t1 <= t0:
        return 0
    first = datetime.fromtimestamp(t0, UTC).astimezone(zone).date() - timedelta(days=1)
    last = datetime.fromtimestamp(t1, UTC).astimezone(zone).date()
    total = 0
    d = first
    while d <= last:
        s = local_to_instant(datetime(d.year, d.month, d.day, 22), zone, True)
        n = d + timedelta(days=1)
        e = local_to_instant(datetime(n.year, n.month, n.day, 6), zone, True)
        lo, hi = max(s, t0), min(e, t1)
        if hi > lo:
            total += hi - lo
        d += timedelta(days=1)
    return total // 60


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
